INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (460, 1, 'create -b', '`qemu-img create -b base.qcow2 top.qcow2` 는 무엇을 만들까요?', '차이만 담아요.', NULL, NULL, '[]', 'choice', '["백킹 파일을 복사한 독립 이미지", "백킹 파일을 압축한 새 이미지", "백킹 파일과의 차이만 기록하는 이미지", "백킹 파일을 잠가 둔 읽기 전용 이미지"]', 2, '문서는 BACKING_FILE 을 주면 그 파일과의 차이만 기록하는 이미지를 만들며 이때는 크기를 따로 지정하지 않아도 된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 2, '백킹 보호', '`create -b` 로 만든 뒤 **백킹 파일** 은 어떻게 될까요?', '커밋 전까지예요.', NULL, NULL, '[]', 'choice', '["VM 이 쓸 때마다 함께 수정된다", "commit 을 하지 않는 한 수정되지 않는다", "생성 직후 자동으로 삭제된다", "생성 직후 압축되어 읽기 전용이 된다"]', 1, '문서는 백킹 파일이 commit(qemu-img commit)을 쓰지 않는 한 절대 수정되지 않는다고 설명합니다.', NULL, NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 3, 'commit 후', '`qemu-img commit top.qcow2` 가 **성공한 뒤** top.qcow2 는 어떻게 될까요?', '비워져요.', NULL, NULL, '[]', 'choice', '["내용이 비워진다", "그대로 변경 없이 남는다", "백킹 파일로 이름이 바뀐다", "자동으로 삭제된다"]', 0, '문서는 commit 이 FILENAME 의 변경을 백킹 파일에 합치고, 성공하면 FILENAME 은 비워지며 필요 없어서 버릴 거라면 -d 로 비우기를 건너뛸 수 있다고 설명합니다.', NULL, NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 4, 'commit -b', '체인에서 `commit -b` 로 **중간 이미지를 BASE** 로 지정해 커밋하면 사이의 이미지는 어떻게 될까요?', '무효가 돼요.', NULL, NULL, '[]', 'choice', '["정상 상태로 그대로 유지된다", "자동으로 하나로 합쳐진다", "읽기 전용으로 바뀌어 안전해진다", "무효가 되어 엉뚱한 데이터를 준다"]', 3, '문서는 commit 뒤 BASE 와 최상위 이미지 사이의 모든 이미지가 무효가 되어 쓰레기 데이터를 돌려줄 수 있으며, 그래서 -b 는 -d 를 함의한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 5, 'rebase 포맷', '`qemu-img rebase` 로 **백킹 파일을 바꿀 수 있는** 포맷은 무엇일까요?', '두 가지예요.', NULL, NULL, '[]', 'choice', '["raw 와 vmdk", "qcow2 와 raw", "qcow2 와 qed", "vdi 와 vhdx"]', 2, '문서는 qcow2 와 qed 포맷만 백킹 파일 변경을 지원한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 6, 'rebase -u', '`qemu-img rebase -u` (unsafe 모드)에 대해 맞는 것은 무엇일까요?', '이름만 바꿔요.', NULL, NULL, '[]', 'choice', '["백킹 파일의 차이를 모두 합쳐 병합한다", "내용 검사 없이 백킹 파일 이름과 포맷만 바꾼다", "이전 백킹 파일이 있어야만 동작한다", "이미지 전체를 압축하며 다시 쓴다"]', 1, '문서는 -u 가 내용 검사 없이 이름과 포맷만 바꾸는 모드로, 백킹 파일을 옮기거나 이름을 바꾼 뒤 고칠 때 쓰이며 새 백킹 파일을 잘못 지정하면 게스트 내용이 손상된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 7, 'snapshot -a', '`qemu-img snapshot -a` 는 무엇을 할까요?', '되돌려요.', NULL, NULL, '[]', 'choice', '["저장된 상태로 되돌린다", "스냅샷을 새로 만든다", "스냅샷을 삭제한다", "스냅샷 목록을 보여 준다"]', 0, '문서는 -a 가 스냅샷을 적용(디스크를 저장 상태로 되돌림)하고, -c 는 생성, -d 는 삭제, -l 은 목록(기본 동작)이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 8, 'compare 종료 코드', '`qemu-img compare` 의 종료 코드 `1` 은 무엇을 뜻할까요?', '결과가 달라요.', NULL, NULL, '[]', 'choice', '["두 이미지가 완전히 같다", "이미지를 여는 중 오류가 났다", "데이터를 읽는 중 오류가 났다", "두 이미지의 내용이 다르다"]', 3, '문서는 compare 의 종료 코드 0 이 같음, 1 이 다름, 2 가 이미지 열기 오류, 3 이 섹터 할당 확인 오류, 4 가 읽기 오류라고 설명합니다.', NULL, NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 9, 'convert -c', '`qemu-img convert -c` 의 **압축** 에 대해 맞는 것은 무엇일까요?', '읽기 전용 압축이에요.', NULL, NULL, '[]', 'choice', '["모든 포맷에서 지원되며 다시 써도 압축된다", "raw 포맷에서만 지원되고 쓰기도 압축된다", "qcow·qcow2 만 지원하며 다시 쓰면 비압축이 된다", "qcow2 에서 지원되나 암호화와 함께만 쓴다"]', 2, '문서는 qcow 와 qcow2 만 압축을 지원하며 압축은 읽기 전용이라 압축된 섹터를 다시 쓰면 비압축 데이터로 기록된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 10, '출력 포맷', 'convert 에서 **출력 포맷** 을 정하는 옵션입니다. 빈칸을 채우세요.', '대문자 O 예요.', NULL, NULL, '[]', 'fill', '["-O", "-f", "-o", "-b"]', NULL, '-O 는 출력 포맷, -f 는 입력 포맷, 소문자 -o 는 포맷별 옵션, -b 는 백킹 파일입니다.', '[0]', 'qemu-img convert -f raw {0} qcow2 disk.img disk.qcow2', NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 11, '스냅샷 만들기', '이미지 안에 **스냅샷을 만드는** 옵션입니다. 빈칸을 채우세요.', 'create 의 c 예요.', NULL, NULL, '[]', 'fill', '["-c", "-a", "-d", "-l"]', NULL, '-c 는 만들기, -a 는 적용, -d 는 삭제, -l 은 목록입니다.', '[0]', 'qemu-img snapshot {0} before-upgrade disk.qcow2', NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]'),
  (460, 12, '오버레이 사용', '백킹 파일 위에 오버레이를 쓰는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 사용 → 확인 → 합치기예요.', NULL, NULL, '[]', 'order', '["`qemu-img create -b` 로 백킹 파일을 둔 오버레이를 만든다", "VM 이 오버레이 이미지에 쓰도록 구성한다", "`qemu-img info --backing-chain` 으로 체인을 확인한다", "VM 을 끈 뒤 `qemu-img commit` 으로 변경을 백킹 파일에 합친다"]', NULL, '문서의 create -b, info --backing-chain, commit 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "QEMU disk image utility (qemu-img)", "url": "https://www.qemu.org/docs/master/tools/qemu-img.html"}]');
